-- 1ClickMela initial Supabase schema. Run once in Supabase SQL Editor.
create extension if not exists pgcrypto;
create table if not exists public.admin_emails(email text primary key,created_at timestamptz default now());
insert into public.admin_emails(email) values ('admin@example.com') on conflict do nothing;
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.admin_emails where lower(email)=lower(coalesce(auth.jwt()->>'email','')))$$;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text,phone text,whatsapp text,created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists public.categories(id uuid primary key default gen_random_uuid(),name text not null,slug text unique not null,image_url text,description text,sort_order int default 0,is_active boolean default true,created_at timestamptz default now());
create table if not exists public.products(id uuid primary key default gen_random_uuid(),name text not null,slug text unique not null,brand text not null,category_id uuid references public.categories(id) on delete set null,price numeric(12,2) not null check(price>=0),compare_at numeric(12,2),description text,features jsonb default '[]',images jsonb default '[]',stock int default 0 check(stock>=0),rating numeric(2,1) default 0,reviews_count int default 0,badge text,sections text[] default '{}',is_active boolean default true,created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists public.banners(id uuid primary key default gen_random_uuid(),eyebrow text,title text not null,body text,button_label text,button_url text,image_url text,sort_order int default 0,is_active boolean default true,created_at timestamptz default now());
create table if not exists public.coupons(id uuid primary key default gen_random_uuid(),code text unique not null,discount_type text not null check(discount_type in ('percentage','fixed','free_shipping')),value numeric(12,2) default 0,min_order numeric(12,2) default 0,max_discount numeric(12,2),starts_at timestamptz default now(),expires_at timestamptz,usage_limit int,usage_count int default 0,is_active boolean default true,created_at timestamptz default now());
create table if not exists public.orders(id uuid primary key default gen_random_uuid(),reference text unique not null,customer_id uuid references auth.users(id) on delete set null,customer_name text not null,email text,phone text not null,whatsapp text,address text not null,city text not null,province text not null,notes text,status text default 'confirmed',payment_method text default 'cod',subtotal numeric(12,2) not null,discount numeric(12,2) default 0,delivery_fee numeric(12,2) default 0,total numeric(12,2) not null,coupon_code text,created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists public.order_items(id uuid primary key default gen_random_uuid(),order_id uuid references public.orders(id) on delete cascade,product_id uuid references public.products(id) on delete set null,product_name text not null,quantity int not null check(quantity>0),unit_price numeric(12,2) not null,image_url text);
create table if not exists public.custom_requests(id uuid primary key default gen_random_uuid(),reference text unique not null,customer_id uuid references auth.users(id) on delete set null,customer_name text not null,email text,phone text not null,whatsapp text,product_name text not null,brand text,target_price numeric(12,2),source_url text,details text,image_urls jsonb default '[]',status text default 'new',quote_amount numeric(12,2),admin_notes text,created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists public.support_requests(id uuid primary key default gen_random_uuid(),reference text unique not null,customer_id uuid references auth.users(id) on delete set null,name text not null,email text not null,phone text,topic text,message text not null,status text default 'new',created_at timestamptz default now());
alter table public.admin_emails enable row level security;alter table public.profiles enable row level security;alter table public.categories enable row level security;alter table public.products enable row level security;alter table public.banners enable row level security;alter table public.coupons enable row level security;alter table public.orders enable row level security;alter table public.order_items enable row level security;alter table public.custom_requests enable row level security;alter table public.support_requests enable row level security;
create policy "public read categories" on public.categories for select using(is_active or public.is_admin());
create policy "public read products" on public.products for select using(is_active or public.is_admin());
create policy "public read banners" on public.banners for select using(is_active or public.is_admin());
create policy "public validate coupons" on public.coupons for select using(is_active or public.is_admin());
create policy "admin categories" on public.categories for all using(public.is_admin()) with check(public.is_admin());
create policy "admin products" on public.products for all using(public.is_admin()) with check(public.is_admin());
create policy "admin banners" on public.banners for all using(public.is_admin()) with check(public.is_admin());
create policy "admin coupons" on public.coupons for all using(public.is_admin()) with check(public.is_admin());
create policy "own profile" on public.profiles for all using(auth.uid()=id or public.is_admin()) with check(auth.uid()=id or public.is_admin());
create policy "create orders" on public.orders for insert with check(customer_id is null or customer_id=auth.uid());
create policy "read own orders" on public.orders for select using(customer_id=auth.uid() or public.is_admin());
create policy "admin update orders" on public.orders for update using(public.is_admin());
create policy "create order items" on public.order_items for insert with check(exists(select 1 from public.orders o where o.id=order_id and (o.customer_id=auth.uid() or o.customer_id is null)));
create policy "read own order items" on public.order_items for select using(exists(select 1 from public.orders o where o.id=order_id and (o.customer_id=auth.uid() or public.is_admin())));
create policy "create custom requests" on public.custom_requests for insert with check(customer_id is null or customer_id=auth.uid());
create policy "read own custom requests" on public.custom_requests for select using(customer_id=auth.uid() or public.is_admin());
create policy "admin update custom requests" on public.custom_requests for update using(public.is_admin());
create policy "create support requests" on public.support_requests for insert with check(customer_id is null or customer_id=auth.uid());
create policy "admin support requests" on public.support_requests for select using(public.is_admin());
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('product-images','product-images',true,5242880,array['image/jpeg','image/png','image/webp']),('custom-requests','custom-requests',false,5242880,array['image/jpeg','image/png','image/webp']) on conflict(id) do nothing;
create policy "public product images" on storage.objects for select using(bucket_id='product-images');
create policy "admin manages product images" on storage.objects for all using(bucket_id='product-images' and public.is_admin()) with check(bucket_id='product-images' and public.is_admin());
create policy "users upload custom images" on storage.objects for insert with check(bucket_id='custom-requests' and auth.uid() is not null);
create policy "owners read custom images" on storage.objects for select using(bucket_id='custom-requests' and ((storage.foldername(name))[1]=auth.uid()::text or public.is_admin()));
